const form = $('Search input').first().json;
const country = form.country || 'Nigeria';
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const id = p.placeId || p.url;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  if (p.permanentlyClosed || p.temporarilyClosed) continue;
  const phone = p.phone || p.phoneUnformatted || '';
  if (!phone) continue;
  out.push({ json: {
    place_id: id,
    business_name: p.title || '',
    category: p.categoryName || (p.categories || [])[0] || '',
    phone,
    website: p.website || '',
    address: p.address || '',
    rating: p.totalScore ?? 0,
    review_count: p.reviewsCount ?? 0,
    maps_url: p.url || '',
    hours: (p.openingHours || []).map(h => h.day + ': ' + h.hours).join(' | '),
    niche: form.niche,
    city: form.city + ', ' + country
  }});
}
return out;

const leads = $('Bundle for scoring').first().json.leads || [];
const r = $input.first().json;
let raw = r.mergedResponse ?? r.content?.parts?.map(p => p.text).join('') ?? r.text ?? r;
let parsed = {};
try {
  if (typeof raw === 'string') { raw = raw.replace(/```json|```/g, '').trim(); parsed = JSON.parse(raw); }
  else parsed = raw;
} catch (e) { parsed = {}; }
const scores = {};
for (const s of (parsed.leads || [])) scores[s.i] = s;
return leads.map((l, i) => {
  const s = scores[i] || {};
  return { json: { ...l, fit_score: Number(s.fit_score ?? 0), why_fit: s.why_fit || '', agent_ideas: s.agent_ideas || '', opener: (s.opener || '').replace(/\s*[\u2014\u2013]\s*/g, ', '), status: 'new', demo_link: '' } };
}).sort((a, b) => b.json.fit_score - a.json.fit_score);

