const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); });

const cityParts = String(p.city || '').split(',').map(s => s.trim());
const where = String(p.city || '') + ' ' + String(p.address || '');
const isNigeria = /nigeria/i.test(where) || !/canada|united states|usa|united kingdom|australia|ireland|new zealand/i.test(where);
const type = clean(prof.demo_type || 'other');
const isClinic = /clinic|dental|med|spa|health|pharma/i.test(type + ' ' + p.category);
const agentName = clean(prof.agent_name) || (isNigeria ? 'Ada' : 'Ava');
const biz = clean(p.business_name);
const emergency = isNigeria ? '112' : '911';

const system = `You are ${agentName}, the ${isNigeria ? 'WhatsApp' : 'website and text'} assistant for ${biz}, a ${clean(p.category)} at ${clean(p.address)}. Phone: ${clean(p.phone)}.
