const f = $('Update form').first().json;
const m = String(f.demo_link || '').match(/webhook\/([0-9a-f-]{36})/i);
if (!m) throw new Error('That does not look like a demo chat link. It should contain /webhook/<id>/chat');
const hookId = m[1].toLowerCase();
const wf = $input.all().map(i => i.json).find(w => (w.nodes || []).some(n => /chatTrigger/.test(n.type) && String(n.webhookId).toLowerCase() === hookId));
if (!wf) throw new Error('No published demo agent uses that chat link.');
const agent = wf.nodes.find(n => n.type === '@n8n/n8n-nodes-langchain.agent');
if (!agent) throw new Error('That workflow has no agent node.');
const clean = s => String(s || '').replace(/\{\{|\}\}/g, '').replace(/\r/g, '').trim();
const menu = clean(f.menu), hours = clean(f.hours), pol = clean(f.policies), extra = clean(f.extra);
const realClient = /real client/i.test(String(f.mode || ''));
if (!menu && !hours && !pol && !extra && !realClient) throw new Error('Nothing to update: fill at least one field.');
const hasMenuTool = wf.nodes.some(n => n.name === 'Get menu');
let sm = String(agent.parameters.options.systemMessage || '');
const startMark = '=== CONFIRMED BUSINESS DETAILS';
const endMark = '=== END CONFIRMED DETAILS ===';
// keep anything confirmed earlier unless a new value is given
const old = (sm.match(/=== CONFIRMED BUSINESS DETAILS[^\n]*\n([\s\S]*?)\n=== END CONFIRMED DETAILS ===/) || [])[1] || '';
const grab = h => (old.match(new RegExp(h + '\\n([\\s\\S]*?)(?=\\n\\n[A-Z ]+\\n|$)')) || [])[1] || '';
const parts = [];
const M = menu || grab('MENU AND SERVICES'); if (M) parts.push('MENU AND SERVICES\n' + M + (hasMenuTool ? '\n(Use this menu and these prices instead of the Get menu tool.)' : ''));
const H = hours || grab('OPENING HOURS'); if (H) parts.push('OPENING HOURS\n' + H);
const P = pol || grab('DELIVERY, BOOKING AND PAYMENT'); if (P) parts.push('DELIVERY, BOOKING AND PAYMENT\n' + P);
const E = extra || grab('OTHER NOTES'); if (E) parts.push('OTHER NOTES\n' + E);
sm = sm.replace(/\n*=== CONFIRMED BUSINESS DETAILS[\s\S]*?=== END CONFIRMED DETAILS ===\n*/, '\n\n');
if (realClient) {
  sm = sm.replace(/THIS IS A SAMPLE DEMO[\s\S]*?\n\n/, '');
  sm = sm.replace(/\(this is a demo business\)/i, '');
}
if (parts.length) {
  const block = startMark + ' (from the owner. These override any sample menu, prices, hours or policies above) ===\n' + parts.join('\n\n') + '\n' + endMark;
  const idx = sm.search(/\nTOOLS\n/);
  if (idx > -1) sm = sm.slice(0, idx) + '\n' + block + '\n' + sm.slice(idx);
  else {
    const t = sm.lastIndexOf('\n\nCurrent');
    sm = t > -1 ? sm.slice(0, t) + '\n\n' + block + sm.slice(t) : sm + '\n\n' + block;
  }
}
sm = sm.replace(/\n{3,}/g, '\n\n');
if (!sm.startsWith('=')) sm = '=' + sm;
agent.parameters.options.systemMessage = sm;
const trig = wf.nodes.find(n => /chatTrigger/.test(n.type));
const settings = {};
for (const k of ['executionOrder', 'timezone', 'saveDataErrorExecution', 'saveDataSuccessExecution', 'saveManualExecutions', 'callerPolicy', 'errorWorkflow']) if (wf.settings && wf.settings[k] !== undefined) settings[k] = wf.settings[k];
return [{ json: {
  id: wf.id,
  name: wf.name,
  business: (trig && trig.parameters && trig.parameters.options && trig.parameters.options.title) || wf.name,
  link: f.demo_link,
  changed: [menu && 'menu', hours && 'hours', pol && 'delivery and payment', extra && 'other notes', realClient && 'demo note removed'].filter(Boolean).join(', '),
  workflow: { name: wf.name, nodes: wf.nodes, connections: wf.connections, settings }
} }];

